/* Generates assets/js/rmci-logo-data.js — the clinic logo embedded as a base64
   data URI so it ALWAYS renders when printing (no path or load-timing issues).
   Run once (or whenever the logo image changes): node tools/gen_logo_data.js  */
const fs = require("fs");
const path = require("path");
const projectRoot = path.resolve(__dirname, "..");

const img = fs.readFileSync(path.join(projectRoot, "assets", "images", "rmci-logo.jpg"));
const b64 = img.toString("base64");
const out =
  "/* Auto-generated by gen_logo_data.js — Rever Medical Center logo as a data URI.\n" +
  "   Embedded so it always renders in the print sheet (no path/load-timing issues). */\n" +
  'const RMCI_LOGO = "data:image/jpeg;base64,' + b64 + '";\n';

fs.writeFileSync(path.join(projectRoot, "assets", "js", "rmci-logo-data.js"), out);
console.log("Wrote assets/js/rmci-logo-data.js (" + Math.round(b64.length / 1024) + " KB)");
